import asyncio; from backend.app.database import SessionLocal; from backend.app.models import ScrapeJob, Workspace; from backend.app.orchestration.discovery_orchestrator import DiscoveryOrchestrator; import uuid; db = SessionLocal(); ws = db.scalar(SessionLocal().query(Workspace).limit(1)); job = ScrapeJob(workspace_id=ws.id, niche="Medspa", country="UK", city="Manchester", target_lead_count=5); db.add(job); db.commit(); db.refresh(job); orchestrator = DiscoveryOrchestrator(db, job, {}); asyncio.run(orchestrator.run_discovery()); db.refresh(job); print("Job 1 Status:", job.status, job.completion_reason, job.leads_scraped); job2 = ScrapeJob(workspace_id=ws.id, niche="Medspa", country="UK", city="Manchester", target_lead_count=100); db.add(job2); db.commit(); db.refresh(job2); orchestrator2 = DiscoveryOrchestrator(db, job2, {}); asyncio.run(orchestrator2.run_discovery()); db.refresh(job2); print("Job 2 Status:", job2.status, job2.completion_reason, job2.leads_scraped);
